DO $$ DECLARE def text; BEGIN def:=pg_get_functiondef('public.close_recurrence_from_deal(uuid)'::regprocedure); def:=replace(def, 'IF auth.uid() IS NOT NULL
     AND NOT (public.user_can_use_tenant(auth.uid(), v_deal.tenant_id) OR public.is_platform(auth.uid())) THEN', 'IF auth.role() IS DISTINCT FROM ''service_role'' AND (auth.uid() IS NULL OR v_deal.tenant_id IS DISTINCT FROM public.get_user_tenant(auth.uid()) OR NOT public.user_can_use_tenant(auth.uid(),v_deal.tenant_id) OR (public.is_rep_only(auth.uid(),v_deal.tenant_id) AND NOT public.rep_owns_contact(auth.uid(),v_deal.contact_id))) THEN'); EXECUTE def; END $$;